-- F-230: existing characters get the geoset-slot values that reproduce their current facialStyle look.
-- GENERATED by Scripts/Character Skins/facial_split.py - do not edit, re-run the script.
-- paint-only choices removed (user 2026-10-31): values of the rules that had them move to the mesh
-- choice carrying that paint, once per character (guid <= the cutoff)
CREATE TABLE IF NOT EXISTS zep_f230_facial_paint_done (guid INT UNSIGNED NOT NULL PRIMARY KEY);
DROP TEMPORARY TABLE IF EXISTS zep_tmp_paint_todo;
CREATE TEMPORARY TABLE zep_tmp_paint_todo (guid INT UNSIGNED NOT NULL PRIMARY KEY);
UPDATE character_customizations AS cc JOIN characters AS c ON c.guid = cc.guid JOIN zep_tmp_paint_todo AS t ON t.guid = cc.guid SET cc.choice = CASE WHEN cc.customization = 11 AND cc.choice IN (11) THEN CASE cc.choice WHEN 11 THEN 6 END ELSE cc.choice END WHERE c.race = 3 AND c.gender = 0;
UPDATE character_customizations AS cc JOIN characters AS c ON c.guid = cc.guid JOIN zep_tmp_paint_todo AS t ON t.guid = cc.guid SET cc.choice = CASE WHEN cc.customization = 10 AND cc.choice IN (5, 6) THEN CASE cc.choice WHEN 5 THEN 2 WHEN 6 THEN 4 END WHEN cc.customization = 12 AND cc.choice IN (5) THEN CASE cc.choice WHEN 5 THEN 4 END ELSE cc.choice END WHERE c.race = 4 AND c.gender = 0;
UPDATE character_customizations AS cc JOIN characters AS c ON c.guid = cc.guid JOIN zep_tmp_paint_todo AS t ON t.guid = cc.guid SET cc.choice = CASE WHEN cc.customization = 10 AND cc.choice IN (7) THEN CASE cc.choice WHEN 7 THEN 2 END WHEN cc.customization = 11 AND cc.choice IN (8) THEN CASE cc.choice WHEN 8 THEN 2 END WHEN cc.customization = 12 AND cc.choice IN (7, 8) THEN CASE cc.choice WHEN 7 THEN 6 WHEN 8 THEN 6 END ELSE cc.choice END WHERE c.race = 7 AND c.gender = 0;
DROP TEMPORARY TABLE zep_tmp_paint_todo;
DROP TEMPORARY TABLE IF EXISTS zep_facial_split;
CREATE TEMPORARY TABLE zep_facial_split (race TINYINT UNSIGNED, gender TINYINT UNSIGNED, facial TINYINT UNSIGNED,
  slot TINYINT UNSIGNED, val TINYINT UNSIGNED, PRIMARY KEY (race, gender, facial, slot));
SELECT c.guid, 10 + m.slot, m.val
FROM characters AS c
JOIN zep_facial_split AS m ON m.race = c.race AND m.gender = c.gender AND m.facial = c.facialStyle;
DROP TEMPORARY TABLE zep_facial_split;
